// Potansiyometre ile LED parlaklığı
const int POT = A0;
const int LED = 9;      // PWM pini (~ işaretli)

void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int deger = analogRead(POT);                 // 0 ... 1023
  int parlaklik = map(deger, 0, 1023, 0, 255); // 0 ... 255
  analogWrite(LED, parlaklik);

  Serial.println(parlaklik);
  delay(50);
}
